const { chromium } = require('playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage({viewport:{width:1280,height:800}});
 const errors=[]; page.on('console',m=>{if(m.type()==='error')errors.push(m.text())}); page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:4173',{waitUntil:'networkidle'});
 await page.locator('[data-section="government"]').click();
 console.log('title1=',await page.locator('#active-title').textText());
 await page.locator('[data-action="welfare"]').click();
 console.log('treasury1=',await page.locator('#treasury-value').textContent());
 await page.locator('[data-speed="2"]').click();
 await page.waitForTimeout(6500);
 console.log('date1=',await page.locator('#date-label').textContent(),'speed-active=',await page.locator('[data-speed="2"]').getAttribute('class'));
 await page.locator('#pause-button').click();
 console.log('pause=',await page.locator('#pause-label').textContent());
 await page.locator('[data-section="economy"]').click();
 console.log('title2=',await page.locator('#active-title').textContent());
 await page.locator('#settings-button').click();
 console.log('dialog=',await page.locator('#settings-dialog').evaluate(d=>d.open));
 await page.locator('.dialog-close').click();
 const saved=await page.evaluate(()=>localStorage.getItem('marafe-game-state-v1'));
 console.log('saved=',saved);
 console.log('errors=',JSON.stringify(errors));
 await browser.close();
})();
